#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char* parse_string(const char* p, int* pos) {
    while (p[*pos] && (p[*pos] == ' ' || p[*pos] == ',' || p[*pos] == '\t' || p[*pos] == '\n' || p[*pos] == '\r')) (*pos)++;
    if (p[*pos] != '"') return NULL;
    int start = ++(*pos);
    while (p[*pos] && p[*pos] != '"') (*pos)++;
    int len = *pos - start;
    char* s = (char*)malloc((size_t)len + 1);
    memcpy(s, p + start, (size_t)len);
    s[len] = '\0';
    if (p[*pos] == '"') (*pos)++;
    return s;
}

int repeatedStringMatch(char* a, char* b) {
    int m = (int)strlen(b);
    int n = (int)strlen(a);
    int* pi = (int*)calloc((size_t)m, sizeof(int));

    for (int i = 1, j = 0; i < m; ++i) {
        while (j > 0 && b[i] != b[j]) j = pi[j - 1];
        if (b[i] == b[j]) ++j;
        pi[i] = j;
    }

    int q = (m + n - 1) / n;
    int limit = (q + 1) * n;

    for (int i = 0, j = 0; i < limit; ++i) {
        char c = a[i % n];
        while (j > 0 && c != b[j]) j = pi[j - 1];
        if (c == b[j]) ++j;
        if (j == m) {
            int start = i - m + 1;
            free(pi);
            return (start + m + n - 1) / n;
        }
    }

    free(pi);
    return -1;
}

