public class Main {
    static String[] parseArgs(String s) {
        s = s.trim();
        if (s.length() < 2) throw new IllegalArgumentException();
        s = s.substring(1, s.length() - 1);
        ArrayList<String> parts = new ArrayList<>();
        int i = 0;
        while (i < s.length()) {
            while (i < s.length() && (s.charAt(i) == ',' || Character.isWhitespace(s.charAt(i)))) i++;
            if (i >= s.length()) break;
            if (s.charAt(i) == '"') {
                int j = i + 1;
                while (j < s.length()) {
                    if (s.charAt(j) == '"' && s.charAt(j - 1) != '\\') break;
                    j++;
                }
                parts.add(s.substring(i + 1, j));
                i = j + 1;
            } else {
                int j = i;
                while (j < s.length() && s.charAt(j) != ',') j++;
                parts.add(s.substring(i, j).trim());
                i = j;
            }
        }
        return parts.toArray(new String[0]);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] vals = parseArgs(line);
        int result = new Solution().repeatedStringMatch(vals[0], vals[1]);
        System.out.println(result);
    }
}

